(()=>{
 const schools={
  chirec:{name:'CHIREC International School',period:'GRADES 11 — 12',title:'A new way<br>to see things.',intro:'For the teachers who made these years feel personal.',teachers:[{name:'Mrs Nirmala Reddy Ma’am',role:'MY PHYSICS TEACHER',time:'Grades 11–12',heading:'Confidence that<br>changed my learning.',body:'Mrs Nirmala Reddy Ma’am supported me throughout Grades 11 and 12. She helped me gain confidence in CBSE Physics, and her guidance made a significant difference to my board examination grades.'},{name:'Mr Bindu Kiran Sir',image:'assets/bindu-kiran-vrajesh.jpg',role:'MY MATHEMATICS TEACHER',time:'Grades 11–12',heading:'Finding an interest<br>in mathematics.',body:'Mr Bindu Kiran Sir taught me mathematics in Grades 11 and 12. He is the person who helped me develop an interest in the subject — an important part of my time at CHIREC.'},{name:'Mrs Prathibha Ma’am',role:'MY HOMEROOM TEACHER',time:'CHIREC International School',heading:'A familiar face.<br>A meaningful connection.',body:'Mrs Prathibha Ma’am is my homeroom teacher and my neighbour. That connection makes her a familiar presence both at school and beyond it.'}]},
  sreenidhi:{name:'Sreenidhi International School',period:'THE EARLIER CHAPTERS',title:'Where curiosity<br>found its roots.',intro:'Remembering the people who have been part of my journey for years.',teachers:[{name:'Mr Ramakrishna Sir',role:'HEAD OF THE SCIENCE DEPARTMENT',time:'Since 2022 · Grade 8',heading:'Years of learning.<br>A lasting foundation.',body:'Mr Ramakrishna Sir, Head of the Science Department, has been my teacher since 2022, when I was in Grade 8. He is an important part of my learning journey at Sreenidhi.'},{name:'Mrs Sahera Banu Ma’am',role:'SERVICE COORDINATOR',time:'Since 2020 · Grade 6',heading:'A connection<br>that began early.',body:'Mrs Sahera Banu Ma’am is the Service Coordinator at Sreenidhi. She has been with me since 2020, when I was in Grade 6 — a connection that goes back to the earlier years of my schooling.'}]}
 };
 const modal=document.createElement('dialog');modal.className='school-dialog';modal.setAttribute('aria-labelledby','school-title');document.body.append(modal);let opener,raf=false;
 function close(){modal.close()}
 function paint(){raf=false;const hero=modal.querySelector('.school-cover');if(!hero)return;const p=Math.min(1,modal.scrollTop/Math.max(1,hero.offsetHeight));modal.style.setProperty('--school-progress',paused?0:p);modal.querySelectorAll('.teacher-story').forEach(story=>{if(story.getBoundingClientRect().top<innerHeight*.9)story.classList.add('teacher-visible')})}
 modal.addEventListener('scroll',()=>{if(!raf){raf=true;requestAnimationFrame(paint)}},{passive:true});
 modal.addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus({preventScroll:true});modal.innerHTML=''});
 document.querySelectorAll('[data-school]').forEach(button=>button.onclick=()=>{opener=button;const school=schools[button.dataset.school];modal.dataset.school=button.dataset.school;modal.innerHTML=`<div class="school-toolbar"><span>V.V / THE FOUNDATIONS</span><button class="school-close" aria-label="Close school story">Back to my journey <span>×</span></button></div><section class="school-cover"><div class="school-atmosphere" aria-hidden="true"><i></i><i></i><i></i><div class="school-orbit"></div></div><div class="school-cover-copy"><p class="school-kicker">${school.name}</p><p class="school-period">${school.period}</p><h2 id="school-title">${school.title}</h2><p class="school-dedication">${school.intro}</p><button class="school-enter">Meet my teachers <span>↓</span></button></div><div class="school-cover-foot"><span>A PERSONAL NOTE OF APPRECIATION</span><span>SCROLL TO DISCOVER ↓</span></div></section><div class="teacher-pages"><div class="teacher-intro"><span>BEHIND EVERY CHAPTER, PEOPLE.</span><p>Some parts of school stay with you.</p></div>${school.teachers.map((teacher,index)=>`<article class="teacher-story"><div class="teacher-margin"><span>0${index+1} / WITH GRATITUDE</span>${teacher.image?`<figure class="teacher-photo"><a href="${teacher.image}" target="_blank" rel="noopener" aria-label="Open photo with Bindu Kiran Sir"><img src="${teacher.image}" alt="Vrajesh with Mr Bindu Kiran Sir" loading="lazy"></a><figcaption>With Bindu Kiran Sir <a href="${teacher.image}" download>Download photo ↓</a></figcaption></figure>`:`<span class="teacher-initial" aria-hidden="true">${['I','II','III'][index]}</span>`}<span>${teacher.time}</span></div><div class="teacher-copy"><p class="teacher-role">${teacher.role}</p><h3>${teacher.name}</h3><h4>${teacher.heading}</h4><p>${teacher.body}</p></div></article>`).join('')}<footer class="school-outro"><p>Part of my story.<br><em>Always.</em></p><span>V. Vrajesh</span><button class="school-return">Return to the foundations ↗</button></footer></div>`;modal.querySelector('.school-close').onclick=close;modal.querySelector('.school-return').onclick=close;modal.querySelector('.school-enter').onclick=()=>modal.scrollTo({top:modal.querySelector('.teacher-pages').offsetTop-65,behavior:paused?'instant':'smooth'});document.body.classList.add('modal-open');modal.showModal();modal.scrollTop=0;modal.querySelector('.school-close').focus({preventScroll:true});paint()});
})();
